t.script:
(function() {
  const PRICES = {
    dog: {
      standard: { small: 60000, medium: 70000, large: 80000 },
      super_premium: { small: 80000, medium: 90000, large: 100000 }
    },
    cat: {
      standard: { kitten: 60000, adult: 70000, senior: 80000 },
      super_premium: { kitten: 80000, adult: 90000, senior: 100000 }
    },
    small_animal: {
      super_premium: { hamster: 100000, junior_rabbit: 100000, adult_rabbit: 150000, guinea_pig: 100000 }
    }
  };

  const BREED_SIZES = {
    dog: [
      { value: 'small', label: 'Small Breeds' },
      { value: 'medium', label: 'Medium Breeds' },
      { value: 'large', label: 'Large Breeds' }
    ],
    cat: [
      { value: 'kitten', label: 'Kitten - (2 - 12 Months)' },
      { value: 'adult', label: 'Adult Cat - (1+ Year)' },
      { value: 'senior', label: 'Senior Cat - (5+ Years)' }
    ],
    small_animal: [
      { value: 'hamster', label: 'Hamster' },
      { value: 'junior_rabbit', label: 'Junior Rabbit (0 - 6 months)' },
      { value: 'adult_rabbit', label: 'Adult Rabbit (6months +)' },
      { value: 'guinea_pig', label: 'Guinea Pig' }
    ]
  };

  const SIZE_LABELS = {
    small: 'Small Breeds',
    medium: 'Medium Breeds',
    large: 'Large Breeds',
    kitten: 'Kitten - (2 - 12 Months)',
    adult: 'Adult Cat - (1+ Year)',
    senior: 'Senior Cat - (5+ Years)',
    hamster: 'Hamster',
    junior_rabbit: 'Junior Rabbit (0 - 6 months)',
    adult_rabbit: 'Adult Rabbit (6months +)',
    guinea_pig: 'Guinea Pig'
  };

  const SERVICES = {
    standard: [
      'Warm Deep Clean Bath',
      'Blow Dry',
      'Ear Care',
      'Full Coat Brush Out',
      'Sanitary Trim (Private Area &amp; Belly)'
    ],
    super_premium: [
      'Warm Deep Clean Bath',
      'Blow Dry',
      'Ear Care',
      'Nail Care',
      'Dental Care',
      'De-shedding',
      'Full Hair Cut or Styling',
      'Flea &amp; Tick Treatment',
      'Paw Balm Treatment',
      'Finishing Touches'
    ]
  };

  let currentTab = 'dog';

  function formatPrice(amount) {
    return 'TZS ' + (amount || 0).toLocaleString();
  }

  function setTab(tab) {
    currentTab = tab;
    document.querySelectorAll('.grooming-tab').forEach(b => {
      b.classList.toggle('active', b.dataset.tab === tab);
    });

    // Update packages grid
    const grid = document.getElementById('packages-grid');
    const cardEssential = document.getElementById('card-essential');
    const cardSignature = document.getElementById('card-signature');
    const priceEssential = document.getElementById('price-essential');
    const priceSignature = document.getElementById('price-signature');

    if (tab === 'small_animal') {
      grid.classList.add('single-col');
      cardEssential.style.display = 'none';
      cardSignature.style.display = 'flex';
      priceSignature.textContent = formatPrice(100000);
    } else {
      grid.classList.remove('single-col');
      cardEssential.style.display = 'flex';
      cardSignature.style.display = 'flex';
      priceEssential.textContent = formatPrice(60000);
      priceSignature.textContent = formatPrice(80000);
    }

    // Sync with form pet_type
    const selectPetType = document.getElementById('field-pet-type');
    if (selectPetType) {
      selectPetType.value = tab;
      updateBreedSizes();
    }

    updatePriceAndDetails();
  }

  function updateBreedSizes() {
    const selectPetType = document.getElementById('field-pet-type');
    const selectBreedSize = document.getElementById('field-breed-size');
    const selectPackage = document.getElementById('field-package');
    const petType = selectPetType.value;

    // Update breed sizes
    selectBreedSize.innerHTML = '<option value="" disabled selected>Breed Size</option>';
    const sizes = BREED_SIZES[petType] || [];
    sizes.forEach(s => {
      const opt = document.createElement('option');
      opt.value = s.value;
      opt.textContent = s.label;
      selectBreedSize.appendChild(opt);
    });

    // Update packages dropdown for small animals
    selectPackage.innerHTML = '<option value="" disabled selected>Service Package</option>';
    if (petType !== 'small_animal') {
      const opt1 = document.createElement('option');
      opt1.value = 'standard';
      opt1.textContent = 'Essential';
      selectPackage.appendChild(opt1);
    }
    const opt2 = document.createElement('option');
    opt2.value = 'super_premium';
    opt2.textContent = 'Signature';
    selectPackage.appendChild(opt2);

    updatePriceAndDetails();
  }

  function updatePriceAndDetails() {
    const petType = document.getElementById('field-pet-type').value;
    const breedSize = document.getElementById('field-breed-size').value;
    const pkg = document.getElementById('field-package').value;

    // What's included box
    const includedBox = document.getElementById('included-box');
    const includedTitle = document.getElementById('included-title');
    const includedList = document.getElementById('included-services');

    if (pkg && SERVICES[pkg]) {
      includedBox.style.display = 'block';
      includedTitle.textContent = "What's included in your " + (pkg === 'standard' ? 'Essential' : 'Signature') + " Package";
      includedList.innerHTML = SERVICES[pkg].map(s => `
        <div class="grooming-service-item">
          <svg class="grooming-check-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
          <span>${s}</span>
        </div>
      `).join('');
    } else {
      includedBox.style.display = 'none';
    }

    // Total Box
    const totalBox = document.getElementById('total-box');
    const totalSummary = document.getElementById('total-summary');
    const totalAmount = document.getElementById('total-amount');

    if (pkg && breedSize && PRICES[petType] && PRICES[petType][pkg] && PRICES[petType][pkg][breedSize]) {
      const price = PRICES[petType][pkg][breedSize];
      const petNameLabel = petType === 'dog' ? 'Dog' : (petType === 'cat' ? 'Cat' : 'Small Animal');
      const sizeLabel = SIZE_LABELS[breedSize] || breedSize;
      const pkgName = pkg === 'standard' ? 'Essential' : 'Signature';

      totalBox.style.display = 'flex';
      totalSummary.textContent = `${petNameLabel} • ${sizeLabel} • ${pkgName} Package`;
      totalAmount.textContent = formatPrice(price);
    } else {
      totalBox.style.display = 'none';
    }
  }

  // Tab click events
  document.querySelectorAll('.grooming-tab').forEach(btn => {
    btn.addEventListener('click', function() {
      setTab(this.dataset.tab);
    });
  });

  // Card click events
  document.querySelectorAll('.grooming-pkg-card').forEach(card => {
    card.addEventListener('click', function() {
      const pkgKey = this.dataset.package;
      const selectPackage = document.getElementById('field-package');
      if (selectPackage) {
        selectPackage.value = pkgKey;
        updatePriceAndDetails();
      }
      const formEl = document.getElementById('booking-form');
      if (formEl) {
        formEl.scrollIntoView({ behavior: 'smooth' });
      }
    });
  });

  // Form input changes
  document.getElementById('field-pet-type').addEventListener('change', function() {
    setTab(this.value);
  });
  document.getElementById('field-breed-size').addEventListener('change', updatePriceAndDetails);
  document.getElementById('field-package').addEventListener('change', updatePriceAndDetails);

  // Sunday date check
  document.getElementById('field-date').addEventListener('change', function() {
    if (!this.value) return;
    const d = new Date(this.value);
    if (d.getDay() === 0) {
      alert("We are closed on Sundays. Please select another day for your pet's grooming.");
      this.value = '';
    }
  });

  // Form submission & WhatsApp redirect
  document.getElementById('grooming-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const petType = document.getElementById('field-pet-type').value;
    const petName = document.getElementById('field-pet-name').value;
    const breedSize = document.getElementById('field-breed-size').value;
    const pkg = document.getElementById('field-package').value;
    const dateStr = document.getElementById('field-date').value;
    const timeStr = document.getElementById('field-time').value;
    const custName = document.getElementById('field-customer-name').value;
    const custPhone = document.getElementById('field-customer-phone').value;

    const basePrice = (PRICES[petType] &amp;&amp; PRICES[petType][pkg] &amp;&amp; PRICES[petType][pkg][breedSize]) || 0;
    const sizeLabel = SIZE_LABELS[breedSize] || breedSize;
    const pkgName = pkg === 'standard' ? 'Essential Package' : 'Signature Package';
    const petTypeLabel = petType === 'dog' ? 'Dog' : (petType === 'cat' ? 'Cat' : 'Small Animal');

    let formattedDate = dateStr;
    try {
      const d = new Date(dateStr);
      formattedDate = d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    } catch(err) {}

    const bookingRef = 'GRM-' + Math.random().toString(36).substring(2, 8).toUpperCase();

    const message = `Hi Stephan's Pet Store!\n` +
      `I want to book a grooming appointment:\n\n` +
      `*GROOMING APPOINTMENT BOOKING*\n` +
      `----------------------------------\n` +
      `*Booking Ref:* #${bookingRef}\n` +
      `*Customer Name:* ${custName}\n` +
      `*Phone Number:* ${custPhone}\n\n` +
      `*PET DETAILS*\n` +
      `*Pet Name:* ${petName} (${petTypeLabel})\n` +
      `*Breed Size:* ${sizeLabel}\n\n` +
      `*SERVICE DETAILS*\n` +
      `*Selected Package:* ${pkgName}\n` +
      `*Preferred Date:* ${formattedDate}\n` +
      `*Preferred Time:* ${timeStr}\n\n` +
      `*PRICE SUMMARY*\n` +
      `  - Package Price: ${formatPrice(basePrice)}\n` +
      `----------------------------------\n` +
      `*Total Amount:* ${formatPrice(basePrice)}\n\n`;

    const whatsappUrl = 'https://wa.me/255769324445?text=' + encodeURIComponent(message);

    // Also post in background to Odoo controller so booking is saved
    const formData = new FormData(this);
    fetch('/grooming/book', {
      method: 'POST',
      body: formData
    }).finally(() => {
      window.location.href = whatsappUrl;
    });
  });

  // Initialize breed sizes on load
  updateBreedSizes();
})();
